import re

def detect(source: str) -> dict:
    """Analyzes source for unguarded mint functions."""
    # Check for mint function body containing recipient assignment to msg.sender
    mint_pattern = re.compile(r'function\s+mint\s*\(.*?\)\s*\{[^}]*?(\w+)\s*=\s*msg\.sender;[^}]*?\}', re.DOTALL)

    # Check for common access control guards
    guard_pattern = re.compile(r'(require|revert|if\s+.*?\s*msg\.sender\s*!=\s*msg\.sender|onlyOwner|onlyMinter)', re.IGNORECASE)

    match = mint_pattern.search(source)
    if match:
        # If mint is found, verify no guard exists in the entire source
        if not guard_pattern.search(source):
            return {
                'flagged': True, 
                'reason': f"Unguarded mint detected: '{match.group(1)}' assigned to msg.sender without visible access control."
            }

    return {'flagged': False, 'reason': 'No unguarded mint pattern identified.'}
